INSERT INTO `coolcareers` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'Actor', 'book_328.pdf', 'thumb_328.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barbara A Somervill, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 328, 'The Career Series', 'Actor', NULL, 'Find out what it takes to make it in the competitive world of professional acting.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(2, 'Air Traffic Controller', 'book_292.pdf', 'thumb_292.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'No', '1000', 292, 'The Career Series', 'Air Traffic Controller', NULL, 'Part of the Career and Tech Education series, this book explains many aspects of the job of a Air Traffic Controller, including training and skills needed.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(3, 'Architects', 'book_87.pdf', 'thumb_87.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Kathleen Manat, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 87, 'The Career Series, Picture Books, Early Concepts with Experiments', 'Architects', NULL, 'With a focus on the importance of science and math knowledge, this book describes architectural feats past and present.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(4, 'Athletic Trainer', 'book_163.pdf', 'thumb_163.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports and Fantasy, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Pat Kummer, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'No', '1000', 163, 'The Career Series, Sports', 'Athletic Trainer', NULL, 'Introduces readers to the cool career of athletic training by giving a better understanding of this cool job.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(5, 'Bioengineer', 'book_295.pdf', 'thumb_295.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Susan H Gray, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 295, 'The Career Series', 'Bioengineer', NULL, 'Bioengineers combine science and engineering to create solutions for many kinds of problems. Find out more about what it takes to succeed as a bioengineer.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(6, 'Chef', 'book_296.pdf', 'thumb_296.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Josh Gregory, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 296, 'The Career Series, Picture Books', 'Chef', NULL, 'Now matter what kind of food your favorite restaurant serves, it is sure to have chefs working behind the scenes. Readers will learn what it is like to work in a busy restaurant kitchen and how they can prepare for a career as a chef.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(7, 'Choreographer', 'book_329.pdf', 'thumb_329.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 329, 'The Career Series', 'Choreographer', NULL, 'Learn about the thrilling world of choreography and find out what it takes to make it in this competitive career.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(8, 'Commercial Fisher', 'book_297.pdf', 'thumb_297.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer:Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barbara A Somervill, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'No', '1000', 297, 'The Career Series', 'Commercial Fisher', NULL, 'Fish are a major source of food for people around the world Find out what it is like to work as a commercial fisher, from living and working on a boat to the hard work required to pull in huge nets of fish.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(9, 'Crime Scene Investigator', 'book_98.pdf', 'thumb_98.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Tamra .B Orr, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'No', '1000', 98, 'The Career Series, Picture Books, Early Concepts with Experiments', 'Crime Scene Investigator', NULL, 'This high-profile career is described, including job tasks, expectations, and educational and personal preparation.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(10, 'Cyber Cop', 'book_99.pdf', 'thumb_99.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Patricia Haynes, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'No', '1000', 99, 'The Career Series, Picture Books, Early Concepts with Experiments', 'Cyber Cop', NULL, 'Law enforcement is keeping up with technology – and the criminals attempting to take advantage of it. Cyber cops use the latest electronic devices to track and find the bad guys.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(11, 'Dancer', 'book_331.pdf', 'thumb_331.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 331, 'The Career Series', 'Dancer', NULL, 'Learn what life is like for a professional dancer and find out if its the right career for you.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(12, 'Electrician', 'book_299.pdf', 'thumb_299.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Micheal Tietelbaum, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 299, 'The Career Series', 'Electrician', NULL, 'Part of the Career and Tech Education series, this book explains many aspects of the job of a Electrician, including training and skills needed.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
(13, 'Environmentalist', 'book_245.pdf', 'thumb_245.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Tamra B Orr, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 245, 'The Career Series, Picture Books', 'Environmentalist', NULL, 'Describes the requirements, education, and duties associated with becoming an environmentalist. Includes profiles of prominent environmentalists.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 19, '0', NULL, NULL),
