(1, 'Farm Animals: Chickens', 'book_41.pdf', 'thumb_41.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Farm Animals, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 41, 'Learning About Animals, Picture Books', 'Farm Animals: Chickens', NULL, 'Describes the physical traits and behavior of chickens and the role that they play on the farm.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 10, '0', NULL, NULL),
(2, 'Farm Animals: Cows', 'book_42.pdf', 'thumb_42.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Farm Animals, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 42, 'Learning About Animals, Picture Books', 'Farm Animals: Cows', NULL, 'Describes the physical traits and behavior of cows and cattle with', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 10, '0', NULL, NULL),
(3, 'Farm Animals: Dogs', 'book_43.pdf', 'thumb_43.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Farm Animals, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 43, 'Learning About Animals, Picture Books', 'Farm Animals: Dogs', NULL, 'Describes the physical traits and behavior of dogs and the role that they play on the farm.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 10, '0', NULL, NULL),
(4, 'Farm Animals: Ducks', 'book_44.pdf', 'thumb_44.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Farm Animals, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 44, 'Learning About Animals, Picture Books', 'Farm Animals: Ducks', NULL, 'Describes the physical traits and behavior of duck and the role that they play on the farm.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 10, '0', NULL, NULL),
(5, 'Farm Animals: Goats', 'book_45.pdf', 'thumb_45.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Farm Animals, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 45, 'Learning About Animals, Picture Books', 'Farm Animals: Goats', NULL, 'Describes the physical traits and behavior of goats and the role that they play on the farm.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 10, '0', NULL, NULL),
(6, 'Farm Animals: Horses', 'book_46.pdf', 'thumb_46.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 46, 'Learning About Animals, Picture Books', 'Farm Animals: Horses', NULL, 'Describes the physical traits and behavior of horses and the role that they play on the farm.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 10, '0', NULL, NULL),
(7, 'Farm Animals: Llama', 'book_53.pdf', 'thumb_53.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Farm Animals, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author:  Language: English, Copyright: 2019, Graphics: Full Color Photographs,', 135, 145, 'Yes', '1000', 53, 'Learning About Animals, Picture Books', 'Farm Animals: Llama', NULL, 'Llamas are strong, useful animals. Their hair is an important source of fiber and they are excellent pack animals. Readers will find out all about the lives of these extraordinary animals.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 10, '0', NULL, NULL),
(8, 'Farm Animals: Pigs', 'book_47.pdf', 'thumb_47.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Farm Animals, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 47, 'Learning About Animals, Picture Books', 'Farm Animals: Pigs', NULL, 'Describes the physical traits and behavior of pigs and the role that they play on the farm.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 10, '0', NULL, NULL),
(9, 'Farm Animals: Sheep', 'book_48.pdf', 'thumb_48.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Farm Animals, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 48, 'Learning About Animals, Picture Books', 'Farm Animals: Sheep', NULL, 'Describes the physical traits and behavior of sheep and the role that they play on the farm.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 10, '0', NULL, NULL),
(10, 'Farm Animals: Turkey', 'book_54.pdf', 'thumb_54.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer:Farm Animals, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 54, 'Learning About Animals, Picture Books', 'Farm Animals: Turkey', NULL, 'Farm-raised turkeys are an important source of food for millions of people. Readers will learn all about the lives of these intriguing animals, from what they eat to how they spend their days.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 10, '0', NULL, NULL);
