INSERT INTO `globalperspectives` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'Genetically Modified Foods', 'book_109.pdf', 'thumb_109.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer:Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Vicky Franchino, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 109, 'Science Explorer', 'Genetically Modified Foods', NULL, 'Should scientists manipulate genes to create new varieties of food? Is genetically modified food safe to eat? How can we grow enough food to feed all the world’s people? Read this book to find out more about genetically modified foods and what people around the world think about them.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 22, '0', NULL, NULL),
(2, 'Global Warming', 'book_111.pdf', 'thumb_111.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Robert Green, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 111, 'Science Explorer, Picture Books, Early Concepts with Experiments', 'Global Warming', NULL, 'Is human activity causing Earth’s to heat up? Is global warming just a natural event? What are the possible effects of global warming? Read this book to learn more about the global warming debate and to start forming your own opinions.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 22, '0', NULL, NULL),
(3, 'Immigration', 'book_119.pdf', 'thumb_119.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Robert Green, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 119, 'The Career Series, Picture Books, Early Concepts with Experiments', 'Immigration', NULL, 'Is immigration a basic human right? Does each country have the right to decide who can enter its borders? What is an illegal immigrant? Start learning about immigration and begin looking at the many different sides of this social issue.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 22, '0', NULL, NULL),
(4, 'Pandemics', 'book_128.pdf', 'thumb_128.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Robert Green, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 128, 'Science Explorer, The Career Series, Picture Books', 'Pandemics', NULL, 'What is a pandemic? What diseases are likely to cause a pandemic? How can the spread of a disease be stopped? Find out about how a disease reaches pandemic proportions and start thinking about what people can do to stop the spread of deadly diseases.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 22, '0', NULL, NULL),
(5, 'Pollution', 'book_131.pdf', 'thumb_131.jpg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'No', '1000', 131, 'Science Explorer, Picture Books', 'Pollution', NULL, 'What causes pollution? How does pollution affect the environment? Why should we care about pollution? Read this book to find out more about the social, environmental, and economic issues related to pollution and what you can do about it.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 22, '0', NULL, NULL),
(6, 'Poverty', 'book_132.pdf', 'thumb_132.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 132, 'Habits and Essentials, Picture Books', 'Poverty', NULL, 'How do you measure poverty? What are the effects of poverty? What can we do to prevent poverty? Learn about poverty and its many faces around the world and to start thinking about what you can do about this global social problem.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 22, '0', NULL, NULL),
(7, 'Watershed Conservation', 'book_152.pdf', 'thumb_152.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Pam Rosenberg, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 152, 'Science Explorer, Habits and Essentials', 'Watershed Conservation', NULL, 'What is a watershed? Why are watersheds important? What is it like to live where there is no clean, safe water supply? Read this book to find out more about the importance of watersheds and how you can help in the fight to keep Earth’s freshwater sources clean and safe.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 22, '0', NULL, NULL);
INSERT INTO `globalproducts` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'Athletic Shoes', 'book_89.pdf', 'thumb_89.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: General, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Dana, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 89, 'Habits and Essentials, Picture Books', 'Athletic Shoes', NULL, 'Which athletic shoe is right for you? Readers will learn about the materials that go into athletic shoes and how athletic shoes are produced and sold to millions of people all around the world.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(2, 'Bicycles', 'book_90.pdf', 'thumb_90.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: General Knowledge, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 90, 'Habits and Essentials, Picture Books, Sports', 'Bicycles', NULL, 'It may be hard to believe in a world full of automobiles, but bicycles are still a favorite means of transportation for many people around the world. This book introduces readers to the history of bicycles and the economics of manufacturing them.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(3, 'Cars', 'book_94.pdf', 'thumb_94.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: James M Flammang, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 94, 'Habits and Essentials, Picture Books', 'Cars', NULL, 'You may have traveled thousands of miles in your family’s car. Did you know that some parts of that car might have traveled halfway around the world before the car ended up in your family’s garage? Look inside to find out more about how cars are manufactured by companies in many different countries.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(4, 'colas', 'book_96.pdf', 'thumb_96.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: General Knowledge, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Kevin Cunningham, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 96, 'Habits and Essentials, Picture Books', 'colas', NULL, 'Did you know that popular cola drinks are bottled, produced, and sold in countries all over the world? Readers will be introduced to the history of cola drinks and learn how American cola companies produce their soft drinks and sell them worldwide.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(5, 'Computers', 'book_171.pdf', 'thumb_171.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Kevin Cunningham, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 171, 'Habits and Essentials, The Career Series, Early Concepts with Experiments', 'Computers', NULL, 'Find out how and where computers are manufactured and the journey they take before they end up in homes, schools and offices.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(6, 'Gasoline', 'book_108.pdf', 'thumb_108.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 108, 'Science Explorer, Picture Book', 'Gasoline', NULL, 'Did you know that gasoline is made from petroleum that is extracted from deep inside Earth? And that the government of Saudi Arabia owns the world’s largest petroleum corporation? Read this book to find out more about how petroleum is turned into gasoline and how that gasoline ends up in the tank of cars around the world.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(7, 'GPS', 'book_253.pdf', 'thumb_253.jpg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habit and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: G S Prentzas, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 253, 'Habits and Essentials', 'GPS', NULL, 'This book takes a product students are interested in, GPS, and provides them with details on how the product is created in the global market place of the 21st century.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(8, 'Radar Guns', 'book_275.pdf', 'thumb_275.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habit and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: G S Prentzas, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 275, 'Habits and Essentials, Picture Books', 'Radar Guns', NULL, 'This book takes a product students are interested in, Radar Gun, and provides them with details on how the product is created in the global market place of the 21st century.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(9, 'Salt', 'book_139.pdf', 'thumb_139.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits & Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author:Robinson Masters, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 139, 'Habits and Essentials', 'Salt', NULL, 'You eat salt everyday, but did you know that only 20% of the world’s salt is consumed as food? Read this book to learn more about how salt is harvested, its other uses, and why wars have been fought over this common, yet important, mineral.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(10, 'Skateboards', 'book_143.pdf', 'thumb_143.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports & Fantasy, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Robert Green, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 143, 'Picture Books, Sports', 'Skateboards', NULL, 'Skateboards are not just popular in America, they are popular in England, China, and Japan as well. This book will help readers understand how raw materials are made into skateboards in factories from California to China.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(11, 'Toys', 'book_222.pdf', 'thumb_222.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Kevin Cunningham, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 222, 'Habits and Essentials', 'Toys', NULL, 'Find out who made the first teddy bear, what fossil fuels have to do with toys. Learn about toys and how they are manufactured.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(12, 'Cell Phones', 'book_95.pdf', 'thumb_95.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: General Knowledge, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Kevin Cunningham, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 95, 'Habits and Essentials', 'Cell Phones', NULL, 'Alexander Graham Bell couldn’t possibly have imagined that one day people the world over would be able to call someone on telephone smaller than the palms of their hands. Readers will discover how cell phone technology has emerged as a global phenomenon, connecting people all over the world to one another.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(13, 'Interactive Whiteboards', 'book_187.pdf', 'thumb_187.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: John Mathews, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 187, 'Habits and Essentials', 'Interactive Whiteboards', NULL, 'Learn more about the Interactive WhiteBoards, how they are made and how they end up in schools and offices around the world.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(14, 'Pencils', 'book_130.pdf', 'thumb_130.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: General, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: kevin Cunningham, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 130, 'Habits and Essentials, Picture Books', 'Pencils', NULL, 'You probably use a pencil almost every day. Did you know that the ‘lead’ in pencil is really a mineral called graphite? And that China and Mexico are two countries with large graphite deposits? Read this book to learn more about how pencils are manufactured and how they end up in the hands of people in countries around the globe.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(15, 'Airplanes', 'book_016.pdf', 'thumb_016.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 16, 'Habits and Essentials, Picture Books', 'Airplanes', NULL, 'Did you know that a jet engine can be made of as many as 25,000 different parts and that those parts come from suppliers around the world? Read this book to find out more about airplanes, how they are manufactured, and how they help make our 21st century global economy possible.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(16, 'DVD_S', 'book_017.pdf', 'thumb_017.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: John Mathews, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'No', '1000', 17, 'Habits and Essentials, Picture Books', 'DVD_S', NULL, 'You may have traveled thousands of miles in your family’s car. Did you know that some parts of that car might have traveled halfway around the world before the car ended up in your family’s garage? Look inside to find out more about how cars are manufactured by companies in many different countries.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(17, 'Jeans', 'book_018.pdf', 'thumb_018.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 18, 'Habits and Essentials, Picture Books', 'Jeans', NULL, 'Looks at the history of the popular clothing item, discussing where and how jeans are made and their impact on the global economy.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL),
(18, 'Mp3 Player', 'book_019.pdf', 'thumb_019.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Robert Green, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 19, 'Habits and Essentials, Picture Books', 'Mp3 Player', NULL, 'Walk down the street of just about any city in the world and you will see someone listening to music on an MP3 player. This book will introduce readers to the history behind the development of MP3 Players and take them on a journey to companies around the world where they are manufactured.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 28, '0', NULL, NULL);
INSERT INTO `growingplants` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'Flowers', 'book_20.pdf', 'thumb_20.jpeg', NULL, NULL, 135, 145, 'Yes', '1000', 20, 'Habits and Essentials', 'Flowers', NULL, 'Flowers look like pretty decorations. Did you know that they also have an important job? Flowers make seeds. Inside each seed is a tiny new plant. Using hands on activities, young readers will be introduced to the amazing world of flowers', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 5, '0', NULL, NULL),
(2, 'Growing New Plants', 'book_21.pdf', 'thumb_21.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habit and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Terry Johnson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 21, 'Save the Planet, Science Explorer, Habits and Essentials', 'Growing New Plants', NULL, 'Some plants in your garden grow every year. Other plants grow all summer but do not return in the spring. Why? Making New Plants explores the various ways that plants grow and reproduce. Using hands on activities, students will gain a better understanding of how plants reproduce', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 5, '0', NULL, NULL),
(3, 'Healing Plants', 'book_22.pdf', 'thumb_22.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Pam Rosenburg, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 22, 'Save the Planet, Science Explorer, Habits and Essentials', 'Healing Plants', NULL, 'Have you ever put aloe on sunburn? Many plants are used to help heal ailments in humans. Using hands on activities, young readers will learn about the many healing properties of plants.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 5, '0', NULL, NULL),
(4, 'Plants Need Sunlight', 'book_24.pdf', 'thumb_24.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Christine Peterson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 24, 'Science Explorer', 'Plants Need Sunlight', NULL, 'Have you ever wondered what plants eat? The truth is amazing. Plants don’t eat at all! Instead, plants make food inside their bodies. Using hands on activities, young readers will be introduced to how plants survive on light, water, and air.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 5, '0', NULL, NULL),
(6, 'Plants We Wear', 'book_26.pdf', 'thumb_26.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Pam Rossenberg, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 26, 'Science Explorer', 'Plants we wear', NULL, 'Do you wear jeans? Did you ever look at the label inside your favorite jeans? It probably said that they are made of cotton. People have been using parts of plants to make cloth for thousands of years. Young readers will develop critical thinking skills as they explore the many plants that we wear.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 5, '0', NULL, NULL),
(7, 'Trees', 'book_30.pdf', 'thumb_30.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Christine Peterson, Language: English, Copyright: 2019, Graphics: Full Color Photograph', 135, 145, 'Yes', '1000', 30, 'Save the Planet, Science Explorer, Picture Books, Early Concepts with Experiments', 'Trees', NULL, 'What are the biggest living things on Earth? Did you guess whales or elephants? The winner is not an animal at all. It is a kind of tree called the coast redwood. Using hands on activities, young readers will be introduced to the amazing world of trees.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 5, '0', NULL, NULL),
(8, 'What is a Plant?', 'book_32.pdf', 'thumb_32.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Pam Rosenberg, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 32, 'Science Explorer, Picture Books, Early Concepts with Experiments', 'What is a Plant?', NULL, 'Have you ever looked at a plant? They seem to come in many different shapes and sizes. But did you know that they all share common elements? Using hands on activities, young readers will be introduced to wonderful world of plants.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 5, '0', NULL, NULL),
(9, 'Plants We Eat', 'book_25.pdf', 'thumb_25.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Jennifer Colby, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 25, 'Science Explorer', 'Plants We Eat', NULL, 'Where does food come from? How many plants do we eat? Using hands on activities, young readers will develop critical thinking skills as they gain a better understanding of the plants we eat.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 5, '0', NULL, NULL);
INSERT INTO `healthyforlife` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'Basketball', 'book_164.pdf', 'thumb_164.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports & Fantasy, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ellen Labrecque, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 164, 'Picture Books, Sports', 'Basketball', NULL, 'In the complex world of the 21st century, the ability to use innovation to solve problems or make products better is a critical skill for kids to possess. This book uses a sport kid’s love, basketball, to highlight how innovation has been used to make the game and the people who play them better.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(2, 'Football', 'book_181.pdf', 'thumb_181.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports and Fantasy, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Jim gigliotti, Language: English, Copyright: 2019, Graphics: Full Color Photographs, 1000 in stock', 145, 165, 'Yes', '1000', 181, 'Sports', 'Football', NULL, 'In the complex world of the 21st century, the ability to use innovation to solve problems or make products better is a critical skill for kids to possess. This book uses a sport kid’s love, football, to highlight how innovation has been used to make the game and the people who play it, better', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(3, 'Hiking', 'book_117.pdf', 'thumb_117.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: General, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: John Mckinney, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 117, 'Picture Books, Sports', 'Hiking', NULL, 'Whether it’s a leisurely stroll through a national park or forest preserve, hiking can be a great activity for connecting with nature and keeping yourself healthy. Students will read and discover more about the proper equipment for hiking, as well as the health benefits of hiking.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(4, 'Motorcycles', 'book_190.pdf', 'thumb_190.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: General, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author:Vicky Franchino, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 190, 'Habits and Essentials, Picture Books', 'Motorcycles', NULL, 'Who was the first person to ride a motorcycle? How did they come up with idea? Who makes the fastest motorcycle? This “Innovation in Transportation” book, Motorcycles, takes a look at the people and creative ideas that have changed the way we think about Motorcycles.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(5, 'Mountain Biking', 'book_124.pdf', 'thumb_124.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: General, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Micheal, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 124, 'Picture Books, Sports', 'Mountain Biking', NULL, 'Mountain biking can be a fun and intense activity that pushes you to the limits. Readers will learn about how they can start their own mountain biking program and begin a lifetime of fitness.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(6, 'Rock climbing', 'book_11137.pdf', 'thumb_137.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ellen Labrecque, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 11137, 'Picture Books, Sports', 'Rock climbing', NULL, 'Rock climbing can be the fun and exhilarating, and the best part is that it is an activity that also helps you stay healthy and fit. Students will learn more about how they can start climbing, the importance of good equipment, and the health benefits of rock climbing.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(7, 'Skateboarding', 'book_142.pdf', 'thumb_142.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports & Fantasy, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Jim Fitzpatrick, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 142, 'Picture Books, Sports', 'Skateboarding', NULL, 'Whether you skateboard for transportation or like to hit the ramps at the local skateboard park, skateboarding is fun and can help you keep fit. Read this book to find out more about skateboarding and how it can help you stay healthy for life.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(8, 'Skiing', 'book_144.pdf', 'thumb_144.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports & Fantasy, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Micheal Teitelbaum, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 144, 'Picture Books, Sports', 'Skiing', NULL, 'Skiing down a snowy slope is fun and exciting. Readers will find out what they need to get started on an outdoor sport that can get them outdoors and help keep them fit for life.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(9, 'Snowboarding', 'book_146.pdf', 'thumb_146.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports & Fantasy, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Jim Fitzpatrick, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 146, 'Picture Books, Sports', 'Snowboarding', NULL, 'Whether you like speeding down snowy slopes or doing jumps and other tricks, snowboarding may be the sport for you. Look inside to find out more about this fast-growing sport and how it can help you stay healthy for life.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(10, 'Soccer', 'book_207.pdf', 'thumb_207.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Jim Buckley, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 207, 'Sport', 'Soccer', NULL, 'Whether you like speeding down snowy slopes or doing jumps and other tricks, snowboarding may be the sport for you. Look inside to find out more about this fast-growing sport and how it can help you stay healthy for life.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(11, 'Surfing', 'book_149.pdf', 'thumb_149.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports & Fantasy, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Jim Fitzpatrick, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 149, 'Picture Books, Sports', 'Surfing', NULL, 'Surfing is not just a great summer sport; it also has amazing health benefits as well. Readers will learn more about the history of surfing, how to get started safely, and the various health benefits of the sport.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(12, 'Running', 'book_138.pdf', 'thumb_138.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ellen Labrecque, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 138, 'Picture Books, Sports', 'Running', NULL, 'You don’t need a lot of expensive equipment to start running. With a good pair of shoes and a desire to challenge yourself physically, you can start running for fun and fitness. Look inside to learn more about how to start running and stay healthy for life.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(13, 'Swimming', 'book_217.pdf', 'thumb_217.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Stephen timblin, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 217, 'Sports', 'Swimming', NULL, 'In the complex world of the 21st century, the ability to use innovation to solve problems or make products better is a critical skill for kids to possess. This book uses a sport kid’s love, swimming, to highlight how innovation has been used to make the sport and the people who compete in it, better.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL),
(14, 'Golf', 'book_020.pdf', 'thumb_020.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: K C Kelley, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 20, 'Sports', 'Golf', NULL, 'Explores how being open to different perspectives, sharing failures and successes with others, and acting on creative ideas has lead to new solutions to old problems in each of the featured sporting arenas.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 21, '0', NULL, NULL);
INSERT INTO `historyseries` (`id`, `book_title`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'History title 1', '2.jpg', '6.jpg', 'Details 1', 250, 120, 'Yes', '20', 12312, 'cat1, cat2, cat3', 'tag1, tag2, tag3', 'Desc 1', 'Add info 1', 35, '0', NULL, NULL);
INSERT INTO `howdidthatgettomyhouse` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'How Did That Get To My House Electricity', 'book_372.pdf', 'thumb_372.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 372, 'Habits and Essential', 'How Did That Get to My House? Electricity', NULL, 'Describes how electricity is produced and transported from the power plant into homes and offices.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 7, '0', NULL, NULL),
(2, 'How Did That Get to My House? Mail', 'book_374.pdf', 'thumb_374.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Geetano Capici, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 374, 'Habits and Essentials', 'How Did That Get to My House? Mail', NULL, 'Describes the postal services and explains how a letter placed in your mailbox can reach almost anyone, anywhere in the world.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 7, '0', NULL, NULL),
(3, 'How Did That Get to My House? Water', 'book_379.pdf', 'thumb_379.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 379, 'Science Explorer', 'How Did That Get to My House? Water', NULL, 'Describes how water is transported, treated and stored from its source into homes, schools, and offices.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 7, '0', NULL, NULL),
(4, 'How Did That Get to My House? Internet', 'book_373.pdf', 'thumb_373.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Gary T, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 373, 'Habits and Essentials', 'How Did That Get to My House?', NULL, 'Describes how the internet works, from how content is developed to how sites from around the world are accessible from your home computer.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 7, '0', NULL, NULL),
(5, 'How Did That Get to My House? Music', 'book_375.pdf', 'thumb_375.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ellen Labrecque, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 375, 'Habits and Essentials', 'How Did That Get to My House? Music', NULL, 'Describes how music reaches your home, from recording, to storage to transmissions.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 7, '0', NULL, NULL),
(6, 'How Did That Get to My House? Natural Gas', 'book_376.pdf', 'thumb_376.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 376, 'Science Explorer, Habits and Essentials', 'How Did That Get to My House? Natural Gas', NULL, 'Describes how the natural gas that is used to cook and heat your home is discovered and transported into your home.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 7, '0', NULL, NULL),
(7, 'How Did That Get to My House? Telephone', 'book_377.pdf', 'thumb_377.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 377, 'Habits and Essentials', 'How Did That Get to My House? Telephone', NULL, 'Describes how the telephone works. Young readers will gain an understanding on how dialing several numbers on a phone enables them to communicate with virtually anyone on earth.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 7, '0', NULL, NULL),
(8, 'How Did That Get to My House? Television', 'book_378.pdf', 'thumb_378.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 378, 'Habits and Essentials', 'How Did That Get to My House? Television', NULL, 'Describes how Television programs are developed and transmitted across the airwaves and into homes, schools, and offices.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 7, '0', NULL, NULL);
