INSERT INTO `howdidtheybuildthat` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'How Did They Build That? Airport', 'book_388.pdf', 'thumb_388.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 388, 'Habits and Essentials', 'How Did They Build That? Airport', NULL, 'This title discusses how airports are built, from runway design and construction to terminal and security.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 17, '0', NULL, NULL),
(2, 'How Did They Build That? Bridge', 'book_389.pdf', 'thumb_389.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 389, 'Habits and Essentials, The Career Series', 'How Did They Build That? Bridge', NULL, 'This title discusses how bridges are built, including engineering, design and construction.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 17, '0', NULL, NULL),
(3, 'How Did They Build That? Dam', 'book_390.pdf', 'thumb_390.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 390, 'Habits and Essentials, The Career Series', 'How Did They Build That? Dam', NULL, 'This title discusses how damns are built, including engineering, design and construction.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 17, '0', NULL, NULL),
(4, 'How Did They Build That? House', 'book_407.pdf', 'thumb_407.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 407, 'Habits and Essentials, The Career Series, Picture Books', 'How Did They Build That? House', NULL, 'Every town or city is filled with houses of all shapes and sizes, but we don’t often stop to think about how they are built. Readers will learn all about the construction process, from foundations to roofs.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 17, '0', NULL, NULL),
(5, 'How Did They Build That? Road', 'book_391.pdf', 'thumb_391.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Sharon Nottinger, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 391, 'Habits and Essentials, The Career Series', 'How Did They Build That? Road', NULL, 'This title discusses how roads are built, from road design and construction to painting and lighting', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 17, '0', NULL, NULL),
(6, 'How Did They Build That? Skyscraper', 'book_393.pdf', 'thumb_393.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Vicky Franchino, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 393, 'Habits and Essentials, The Career Series', 'How Did They Build That? Skyscraper', NULL, 'This title discusses how skyscrapers are built, including engineering, design and construction.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 17, '0', NULL, NULL),
(7, 'How Did They Build That? Tunnel', 'book_395.pdf', 'thumb_395.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Vicky Franchino, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 395, 'Habits and Essentials, The Career Series', 'How Did They Build That? Tunnel', NULL, 'This title discusses how tunnels are built, from planning and excavation to construction to site design.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 17, '0', NULL, NULL),
(8, 'How Did They Build That? Zoo', 'book_449.pdf', 'thumb_449.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Tamra B Orr, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 449, 'Habits and Essentials, Picture Books', 'How Did They Build That? Zoo', NULL, 'Learn how zoos are built and what sorts of things zoo builders need to think of before construction begins.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 17, '0', NULL, NULL),
(9, 'How Did They Build That? School', 'book_392.pdf', 'thumb_392.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author:Matt Mullins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 392, 'Habits and Essentials, The Career Series', 'How Did They Build That? School', NULL, 'This title discusses how schools are built, including engineering, design and construction.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 17, '0', NULL, NULL),
(10, 'How Did They Build That? Water Park', 'book_408.pdf', 'thumb_408.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 408, 'Habits and Essentials, The Career Series', 'How Did They Build That? Water Park', NULL, 'Tall, twisting slides, gigantic wave pools, and powerful waterfalls are all common sights at a water park. Readers will find out what it takes to plan and build these fun places.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 17, '0', NULL, NULL),
(11, 'How Did They Build That? Lighthouse', 'book_448.pdf', 'thumb_448.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 448, 'Habits and Essentials, Picture Books', 'How Did They Build That? Lighthouse', NULL, 'Find out how lighthouses work and how they have changed throughout history.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 17, '0', NULL, NULL),
(12, 'How Did They Build That? Stadium', 'book_394.pdf', 'thumb_394.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author:Matt Mullins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 394, 'Habits and Essentials, The Career Series', 'How Did They Build That? Stadium', NULL, 'This title discusses how sports stadiums are built, including engineering, design and construction.', 'Weight : 9.6 g, Dimensions : 8 × 8 × 4 cm', 17, '0', NULL, NULL);
INSERT INTO `howdoesthatfly` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'How Does It Fly Blimp', 'book_450.pdf', 'thumb_450.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Sharon Nittinger, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 135, 'No', '1000', 450, 'Habits and Essentials, Picture Books', 'How Does It Fly? Blimp', NULL, 'Blimps were once a popular form of transportation. Find out how they work and why they are not so common anymore.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 9, '0', NULL, NULL),
(2, 'How Does It Fly Glider', 'book_453.pdf', 'thumb_453.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 135, 'No', '1000', 453, 'Habits and Essentials, Picture Books', 'How Does It Fly? Glider', NULL, 'Find out how these interesting vehicles can fly without engines.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 9, '0', NULL, NULL),
(3, 'How Does It Fly? Helicopter', 'book_454.pdf', 'thumb_454.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 454, 'Habits and Essentials, Picture Books', 'How Does It Fly? Helicopter', NULL, 'Learn how a spinning set of blades makes a helicopter fly and find out how pilots steer these interesting vehicles.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 9, '0', NULL, NULL),
(4, 'How Does It Fly? Jet Plane', 'book_456.pdf', 'thumb_456.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 456, 'Habits and Essentials, Picture Books', 'How Does It Fly? Jet Plane', NULL, 'Learn all about how these speedy airplanes were created, how they work, and how they help us travel.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 9, '0', NULL, NULL),
(5, 'How Does It Fly? Propeller Plane', 'book_457.pdf', 'thumb_457.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 457, 'Habits and Essentials, Picture Books', 'How Does It Fly? Propeller Plane', NULL, 'The earliest airplanes all used propellers to fly. Find out how these planes work and how they were used.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 9, '0', NULL, NULL),
(6, 'How Does It Fly? Hot Air Balloon', 'book_455.pdf', 'thumb_455.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 455, 'Habits and Essentials, Picture Books', 'How Does It Fly? Hot Air Balloon', NULL, 'Find out how these beautiful balloons float through the air and discover what makes them fly.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 9, '0', NULL, NULL),
(7, 'How Does It Fly? Bomber Plane', 'book_451.pdf', 'thumb_451.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Matt Mullins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 451, 'Habits and Essentials, Picture Books', 'How Does It Fly? Bomber Plane', NULL, 'Discover what makes bomber planes different from regular airplanes and learn how they have been used throughout history.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 9, '0', NULL, NULL),
(8, 'How Does It Fly? Fighter Plane', 'book_452.pdf', 'thumb_452.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 452, 'Habits and Essentials, Picture Books', 'How Does It Fly? Fighter Plane', NULL, 'Since airplanes were first invented, they have often been used for military purposes. Learn about different kinds of fighter planes and find out how they are differen from regular planes.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 9, '0', NULL, NULL);
