INSERT INTO `howtowriteseries` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'How to Write a Book Report', 'book_302.pdf', 'thumb_302.jpg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept and Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 302, 'How To Write Series', 'How to Write a Book Report', NULL, 'Book reports are a great way for young people to share their thoughts about books they have read. The activities in this book will help readers develop the skills needed to identify important information from a text and write a clear and concise book report.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(2, 'How To Write About Your Adventure', 'book_348.pdf', 'thumb_348.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'No', '1000', 348, 'How To Write Series', 'How To Write About Your Adventure', NULL, 'Find out how you can create interesting stories based on your real-life experiences.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(3, 'How to Write a How To', 'book_344.pdf', 'thumb_344.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'No', '1000', 344, 'How To Write Series', 'How to Write a How To', NULL, 'New addition to the award winning Language Arts Explorer Jr series, this titles teaches students how to write a “how to” essay.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(4, 'How To Write A Journal', 'book_303.pdf', 'thumb_303.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer:Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author:Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 303, 'How To Write Series', 'How to Write a Journal', NULL, 'Journaling is a popular activity that allows people of all ages to write about their lives. Readers will learn how to write journal entries to record their daily activities and observations.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(5, 'How to Write a Letter', 'book_304.pdf', 'thumb_304.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 304, 'How To Write Series', 'How to Write a Letter', NULL, 'Letter writing is an important skill. Readers will complete activities that teach the basic formatting and composition skills needed to write a perfect letter every time.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(6, 'How to Write an Ad', 'book_349.pdf', 'thumb_349.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M., Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 349, 'How To Write Series', 'How to Write an Ad', NULL, 'Discover how to write a persuasive advertisement.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(7, 'How to Write a News Article', 'book_345.pdf', 'thumb_345.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 345, 'How To Write Series', 'How to Write a News Article', NULL, 'New addition to the award winning Language Arts Explorer Jr series, this titles teaches students how to write a news article.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(8, 'How to Write an Interview', 'book_307.pdf', 'thumb_307.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'No', '1000', 307, 'How To Write Series', 'How to Write an Interview', NULL, 'A great interview is more than just two people talking. An interviewer must learn how to ask the right questions. The activities in this book will help the reader learn more about interviews and how to turn an interview into interesting text.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(9, 'How to Write a Poem', 'book_305.pdf', 'thumb_305.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'No', '1000', 305, 'How To Write Series', 'How to Write a Poem', NULL, 'Writing poems can help teach new ways of thinking about words and their meanings. A poet must consider the sound of the words written on the page. Readers will use the activities in this book to develop their poetry writing skills.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(10, 'How to Write a Report', 'book_346.pdf', 'thumb_346.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Cecilia Minden, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 346, 'Habits and Essentials, Picture Book', 'How to Write a Report', NULL, 'Learn how to research a subject and give a detailed report on the information you discovered.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(11, 'How to Write a Review', 'book_347.pdf', 'thumb_347.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 347, 'How To Write Series', 'How to Write a Review', NULL, 'New addition to the award winning Language Arts Explorer Jr series, this titles teaches students how to write review.Ce', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(12, 'How to Write an E-mail', 'book_306.pdf', 'thumb_306.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer:Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 306, 'How To Write Series', 'How to Write an E-mail', NULL, 'E-mail is a popular form of communication. People use it to chat with friends and conduct business. The activities in this book will teach readers what it takes to write e-mail for any situation.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(13, 'How to Write a Fairy Tale', 'book_343.pdf', 'thumb_343.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 343, 'How To Write Series', 'How to Write a Fairy Tale', NULL, 'New addition to the award winning Language Arts Explorer Jr series, this titles teaches students how to write a fairy tale.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL),
(14, 'How to Write and Give a Speech', 'book_350.pdf', 'thumb_350.jpg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 350, 'Picture Books', 'How to Write and Give a Speech', NULL, 'Learn how to organize your ideas for a speech and how to talk in front of an audience.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 13, '0', NULL, NULL);
