INSERT INTO `juniorscientists` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'Think Like a Scientist in the Backyard', 'book_360.pdf', 'thumb_360.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Matt Mullins, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Matt Mullins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '999', 360, 'Early Concepts with Experiments', 'Think Like a Scientist in the Backyard', NULL, 'Complete a variety of fun science experiments in your own backyard.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(2, 'Think Like a Scientist in the Classroom', 'book_362.pdf', 'thumb_362.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Matt Mullins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 155, 'Yes', '999', 362, 'Early Concepts with Experiments', 'Think Like a Scientist in the Classroom', NULL, 'Complete a variety of fun science experiments using the items found in your classroom at school.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(3, 'Junior Scientists: Experiment with Rocks', 'book_313.pdf', 'thumb_313.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Sophie Lockwood, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 185, 'Yes', '1000', 313, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Rocks', NULL, 'Describes experiments that can be performed using rocks to demonstrate their properties, including how they are formed, how to test their hardness, and whether rock layers can be changed by events such as earthquakes.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(4, 'Junior Scientists: Experiment with Bugs', 'book_308.pdf', 'thumb_308.jpg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 185, 'No', '1000', 308, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Bugs', NULL, 'Provides step-by-step instructions for performing experiments with insects, investigating various prinicples about their behavior.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(5, 'Junior Scientists: Experiment with Heat', 'book_309.pdf', 'thumb_309.jpg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 309, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Heat', NULL, 'Introduces simple scientific principles involving heat, and provides instructions for experiments that can be done at home to prove them.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
