(7, 'Junior Scientists: Experiment with Plants', 'book_312.pdf', 'thumb_312.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Susan H Gray, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 312, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Plants', NULL, 'Describes experiments that can be performed with plants in order to learn about their properties, including whether roots grow before stems, the importance of light, and how plants drink water.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(8, 'Junior Scientists: Experiment with Seeds', 'book_314.pdf', 'thumb_314.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Susan H Gray, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 314, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Seeds', NULL, 'Describes experiments that can be performed with seeds in order to learn about their properties such as how water temperature affects seeds, the direction roots grow, and the effect of talk on plant growth.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(9, 'Junior Scientists: Experiment with Soil', 'book_315.pdf', 'thumb_315.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Vicky Franchino, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 315, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Soil', NULL, 'Describes experiments that can be performed with soil in order to learn about its properties, including its composition, whether it can act as a natural filter, and if different substances can make it more fertile.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(10, 'Junior Scientists: Experiment with Solids', 'book_317.pdf', 'thumb_317.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer:Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Josh Gregory, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 317, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Solids', NULL, 'Describes the physical properties of solids and explains how matter can change to and from a solid into a liquid or gas.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(11, 'Junior Scientists: Experiment with Solar Energy', 'book_316.pdf', 'thumb_316.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Christine Taylor, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 316, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Solar Energy', NULL, 'Describes experiments that can be performed using solar energy in order to learn about its properties, including how different colors absorb sunlight, if it cleans dirty water, and whether it can cook food.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(12, 'Junior Scientists: Experiment with Water', 'book_318.pdf', 'thumb_318.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Charnon Sharon, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 318, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Water', NULL, 'Presents experiments demonstrating the basic scientific principles of water, including information on erosion, precipitation, and condensation.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(13, 'Junior Scientists: Experiment with Weather', 'book_319.pdf', 'thumb_319.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept With Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Tamra B Orr, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 319, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Weather', NULL, 'Provides step-by-step instructions for performing experiments designed to answer such questions about the weather as what makes it rain, how do scientists measure air pressure, and how does temperature affect air movement.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(14, 'Think Like a Scientist in the Car', 'book_361.pdf', 'thumb_361.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Matt Mullins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 361, 'Early Concepts with Experiments', 'Think Like a Scientist in the Car', NULL, 'Complete a variety of fun science experiments dealing with cars.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(15, 'Think Like a Scientist in the Garden', 'book_363.pdf', 'thumb_363.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Matt Mullins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 363, 'Early Concepts with Experiments', 'Think Like a Scientist in the Garden', NULL, 'Complete a variety of fun science experiments with the plants in your garden.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
