(17, 'Think Like a Scientist on the Playground', 'book_366.pdf', 'thumb_366.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Matt Mullins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 155, 'Yes', '998', 366, 'Early Concepts with Experiments', 'Think Like a Scientist on the Playground', NULL, 'Complete a variety of fun science experiments using the equipment at your favorite playground.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(18, 'Think Like a Scientist in the Kitchen', 'book_365.pdf', 'thumb_365.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Matt Mullins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'No', '999', 365, 'Early Concepts with Experiments', 'Think Like a Scientist in the Kitchen', NULL, 'Complete a variety of fun science experiments using common kitchen items.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(19, 'Girl Scientists', 'book_021.pdf', 'thumb_021.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Virginia Loh-Hagan, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 21, 'Habits and Essentials', 'Experiment with Magnets', NULL, 'Who were history\'s smartest scientists? Who was voted \"Most Likely to Have the Best Garden?\" In the History\'s Yearbook series, readers will learn about the amazing and diverse women in history. In Girl Scientists, readers will discover and rediscover their favorite heroines and learn about top women scientists who have made an impact. Each book in this series is written at a higher maturity level using considerate text at a lower reading level in order to engage struggling readers. Backmatter material includes writing prompts that encourage readers to think creatively and critically. Series includes, a table of contents, educational sidebars, bibliography, glossary, index, and author biography.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL),
(20, 'Junior Scientists: Experiment with Magnets', 'book_311.pdf', 'thumb_311.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Christine Taylor, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 311, 'Early Concepts with Experiments', 'Junior Scientists: Experiment with Magnets', NULL, 'Presents experiments and activities that demonstrate the concepts and scientific principles of magnetism.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 16, '0', NULL, NULL);
