INSERT INTO `learningonlineetiquette` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'Find the Right Site', 'book_247.pdf', 'thumb_247.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ann, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 247, 'Habits and Essentials, The Career Series, Early Concepts with Experiment', 'Find the Right Site', NULL, 'Super Smart Information Strategies: Find the Right Site provides students with practical information on how to evaluate web sites. Readers are encouraged to think critically as they conduct research, collaborate with fellow students and present their findings in new and different ways.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(2, 'Find Your Way Online', 'book_248.pdf', 'thumb_248.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Career Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Suzy, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'No', '1000', 248, 'Habits and Essentials, The Career Series', 'Find Your Way Online', NULL, 'Super Smart Information Strategies: Find your way Online provides students with practical information on how to use online resources. Readers are encouraged to think critically as they conduct research, collaborate with fellow students and present their findings in new and different ways.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
