(7, 'Make the Grade', 'book_262.pdf', 'thumb_262.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Carol A Gordon, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 262, 'Habits and Essentials, The Career Series', 'Make the Grade', NULL, 'Super Smart Information Strategies: Make the Grade provides students with practical information for evaluating product and process associated with the conducting and presenting research. Readers are encouraged to think critically as they conduct research, collaborate with fellow students and present their findings in new and different ways.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(8, 'Mind Your Manners Online', 'book_352.pdf', 'thumb_352.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Phyllis Cornwall, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 352, 'Habits and Essentials', 'Mind Your Manners Online', NULL, 'Introduces proper online etiquette for children, including respect, fairness, responsibilty, and manners.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
