(12, 'Put It All Together', 'book_273.pdf', 'thumb_273.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept Work, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Phyllis Cornwall, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 273, 'The Career Series, Early Concepts with Experiments', 'Put It All Together', NULL, 'Super Smart Information Strategies: Pull it Together provides students with practical information on how to synthesizing data. Readers are encouraged to think critically as they conduct research, collaborate with fellow students and present their findings in new and different ways.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(13, 'Shooting Video to Make Learning Fun', 'book_325.pdf', 'thumb_325.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Julie Green, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 325, 'Habits and Essentials, Early Concepts with Experiments', 'Shooting Video to Make Learning Fun', NULL, 'This books helps students learn how to harness the power of video to inform and entertain. Includes background information and practical hands on activities.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(14, 'Team up Online', 'book_286.pdf', 'thumb_286.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Vicky Pascaretti, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 286, 'Early Concepts with Experiments', 'Team up Online', NULL, 'Super Smart Information Strategies: Team up Online provides students with practical information for online collaboration. Readers are encouraged to think critically as they conduct research, collaborate with fellow students and present their findings in new and different ways.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(15, 'Using Digital Images', 'book_327.pdf', 'thumb_327.jpeg', NULL, 'Age : 3 and up Series: Language Arts Explorer: Concept with Experiments No pf Pages: 32 pages Publisher: Aries Books International. (January 1, 2019) Author: Suzy Rabbat Language: English Copyright: 2019 Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 327, 'Science Explorer, Early Concepts with Experiments', 'Using Digital Images', NULL, 'An instructional guide created for youngsters tells them what they need to know to capture and share those special events digitally.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(16, 'Write It Down', 'book_291.pdf', 'thumb_291.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Julie Green, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 291, 'Early Concepts with Experiments', 'Write It Down', NULL, 'Super Smart Information Strategies: Write it Down provides students with practical information on how to develop note taking skills. Readers are encouraged to think critically as they conduct research, collaborate with fellow students and present their findings in new and different ways.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
