(18, 'Find New Words with Dictionaries', 'book_335.pdf', 'thumb_335.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ann Truesdell, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 335, 'Habits and Essentials, Early Concepts with Experiments', 'Find New Words with Dictionaries', NULL, 'So many words, so little time! This exciting new title from Aries bookse publishing helps students understand and harness the power of print and electronic dictionaries.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(19, 'Find the Facts with Encyclopedias', 'book_336.pdf', 'thumb_336.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ann Truesdell, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 336, 'Habits and Essentials, The Career Series, Early Concepts with Experiments', 'Find the Facts with Encyclopedias', NULL, 'This new offering from Aries Books & Publishing, was developed to educate young readers on how to use both print and electronic encyclopedias.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(20, 'Find the Right Words with Thesauruses', 'book_337.pdf', 'thumb_337.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ann Truesdell, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 337, 'Habits and Essentials, The Career Series, Early Concepts with Experiments', 'Find the Right Words with Thesauruses', NULL, 'How many times have your students struggled to find the best word to describe a feeling, a scene, or an impression? This new title from Aries Books and Publishers helps explain to young readers how a thesaurus can be used to help them become more precise and descriptive in their writing.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(21, 'Get to the Right Site', 'book_341.pdf', 'thumb_341.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ann Truesdell, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 341, 'Early Concepts with Experiments', 'Get to the Right Site', NULL, 'Describes how to evaluate websites, discussing how to assess their accuracy, authorship, and purpose.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(22, 'Go Straight to the Source', 'book_252.pdf', 'thumb_252.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 252, 'The Career Series', 'Go Straight to the Source', NULL, 'Super Smart Information Strategies: Go straight to the Source provides students with practical information on how to use primary sources. Readers are encouraged to think critically as they conduct research, collaborate with fellow students and present their findings in new and different ways.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
(23, 'Social Studies Projects that Shine', 'book_357.pdf', 'thumb_357.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concepts with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Sara Wilkie, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '999', 357, 'Early Concepts with Experiments', 'Social Studies Projects that Shine', NULL, 'Find out how you can create top notch social studies projects.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 14, '0', NULL, NULL),
