INSERT INTO `maths` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(2, 'Giving Back', 'book_189.pdf', 'thumb_189.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habit and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 189, 'Habits and Essentials, Picture Books', 'Giving Back', NULL, 'Do you have time, talent, or money that you can use to help others in need? Have you ever wondered which charities you should support or how much you can afford to give? Read this book to find out more about how your math skills can help you give back to your community.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(3, 'Mountains', 'book_266.pdf', 'thumb_266.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Picture Book, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 266, 'Habits and Essentials, Picture Books', 'Mountains', NULL, 'This book uses math and science to help students learn about mountains. Math challenge questions provide students with the opportunity to apply math skills as they learn about the characteristics of mountains.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(4, 'Oceans', 'book_268.pdf', 'thumb_268.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Amazing Picture Books with  Math, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ann Heinrichs, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '999', 268, 'Maths -Do it with numbers, Planets & Earth\'s Geography, Picture Books, Early Concepts with Experiments', 'Oceans', NULL, 'This book uses math and science to help students learn about oceans. Math challenge questions provide students with the opportunity to apply math skills as they learn about the characteristics of oceans.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(5, 'Rivers', 'book_277.pdf', 'thumb_277.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Do it with numbers, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: John Nestor, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 277, 'Maths -Do it with numbers, Planets & Earth\'s Geography, Picture Books', 'Rivers', NULL, 'This book uses math and science to help students learn about rivers. Math challenge questions provide students with the opportunity to apply math skills as they learn about the characteristics of rivers.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(6, 'Saving for the future', 'book_140.pdf', 'thumb_140.jpg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Save the planet, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 140, 'Save the Planet, Habits and Essentials, Picture Books', 'Saving for the future', NULL, 'Is there something you want or need that you don’t have the money for? This book introduces readers to financial goal-setting and how to set up a savings plan. Real world examples help readers learn the importance of math skills for money management.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(7, 'Tennis', 'book_220.pdf', 'thumb_220.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 220, 'Picture Books, Sports', 'Tennis', NULL, 'Learn about the connection between math and tennis.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(8, 'Volcanoes', 'book_288.pdf', 'thumb_288.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Do it with numbers, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: john Nestor, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 288, 'Maths -Do it with numbers, Science Explorer, Picture Books', 'Volcanoes', NULL, 'This book uses math and science to help students learn about volcanoes. Math challenge questions provide students with the opportunity to apply math skills as they learn about the characteristics of volcanoes.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(9, 'Glaciers', 'book_251.pdf', 'thumb_251.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barbara A Somerville, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 251, 'Science Explorer, Habits and Essentials, Picture Books', 'Glaciers', NULL, 'This book uses math and science to help students learn about glaciers. Math challenge questions provide students with the opportunity to apply math skills as they learn about the characteristics of glaciers.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(10, 'Islands', 'book_258.pdf', 'thumb_258.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Picture Books, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ann Heinrichs, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 258, 'Maths -Do it with numbers, Picture Books', 'Islands', NULL, 'This book uses math and science to help students learn about Islands. Math challenge questions provide students with the opportunity to apply math skills as they learn about the characteristics of islands.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(11, 'Plains and Plateaus', 'book_270.pdf', 'thumb_270.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Do it with Numbers, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: barbara. A Somervill, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 270, 'Maths -Do it with numbers, Planets & Earth\'s Geography', 'Plains and Plateaus', NULL, 'This book uses math and science to help students learn about plains and plateaus. Math challenge questions provide students with the opportunity to apply math skills as they learn about the characteristics of plains and plateaus.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(12, 'Running', 'book_202.pdf', 'thumb_202.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Sports & Fantasy, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 202, 'Maths -Do it with numbers, Sports', 'Running', NULL, 'Learn about the connection between math and running.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(13, 'Speed Skating', 'book_210.pdf', 'thumb_210.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Do it with numbers, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 210, 'Maths -Do it with numbers, Early Concepts with Experiments, Sports', 'Speed Skating', NULL, 'Learn about the connection between math and speed skating.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(15, 'Cooking by numbers', 'book_003.pdf', 'thumb_003.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 3, 'Maths Do It With Numbers', 'Cooking by numbers', NULL, 'Shows readers how simple math skills can help them plan and prepare nutritious meals.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(16, 'Dinner by Numbers', 'book_004.pdf', 'thumb_004.jpg', NULL, 'Age : 8 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 4, 'Maths-Do It With Numbers', 'Dinner by Numbers', NULL, 'Shows readers how simple math skills can help them make healthy dinner choices.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(17, 'Gardening by numbers', 'book_005.pdf', 'thumb_005.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 5, 'Planets & Earth\'s Geography, Picture Books', 'Gardening by numbers', NULL, 'Shows readers how simple math skills can help them when planning, planting, and harvesting a garden.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(18, 'Grocery shopping by numbers', 'book_006.pdf', 'thumb_006.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 6, 'Planets & Earth\'s Geography, Picture Books', 'Grocery shopping by numbers', NULL, 'Shows readers how simple math skills can help them plan a trip to the grocery store and eat well on a budget.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(20, 'Payday', 'book_007.pdf', 'thumb_007.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 7, 'Planets & Earth\'s Geography, Picture Books', 'Payday', NULL, 'Looks at how math skills can help readers manage money and answers such questions as \"What is a paycheck?\" and \"Why is money deducted from a paycheck?\"', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(22, 'Smart Shopping', 'book_008.pdf', 'thumb_008.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 8, 'Planets & Earth\'s Geography, Picture Books', 'Smart Shopping', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(23, 'Starting Your Own Business', 'book_11119.pdf', 'thumb_009.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 11119, 'Planets & Earth\'s Geography, Picture Books', 'Starting Your Own Business', NULL, 'Have you ever thought up a great business idea but not known how to make it a reality? This book introduces readers to early entrepreneurial strategies. Real world examples help readers learn the importance of math skills for money management. Callouts prompt inquiry, further thinking, and close examination of photographs. Additional text features and search tools, including a glossary and an index, help students locate information and learn new words.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(24, 'Exercise by the Numbers', 'book_105.pdf', 'thumb_105.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Do it with numbers, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author:Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 105, 'Maths -Do it with numbers, Early Concepts with Experiments', 'Exercise by the Numbers', NULL, 'Exercise is an essential component of a healthy lifestyle. Readers will learn about the health benefits of exercise and discover how they can use math to get the most from an exercise routine.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(25, 'Lunch by numbers', 'book_11156.pdf', 'thumb_56.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 11156, 'Habits and Essentials', 'Lunch by numbers', NULL, 'Shows readers how simple math skills can help them make healthy lunch choices.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(26, 'Breakfast by Numbers', 'book_269.pdf', 'thumb_269.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 269, 'Maths -Do it with numbers, Planets & Earth\'s Geography, Picture Books, Early Concepts with Experiments', 'Breakfast by Numbers', NULL, 'Show readers how simple math skills can help them make healthy breakfast choices.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(27, 'Continents', 'book_241.pdf', 'thumb_241.jpg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Planets and Geography, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ann, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 241, 'Planets & Earth\'s Geography, Picture Books', 'Continents', NULL, 'This book uses math and science to help students learn about Continents. Math challenge questions provide students with the opportunity to apply math skills as they learn about the characteristics of the world’s continents.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL),
(28, 'Restaurants by numbers', 'book_11402.pdf', 'thumb_402.jpg', NULL, 'Age : 7 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 11402, 'Habits and Essentials', 'Restaurants by numbers', NULL, 'Shows readers how simple math skills can help them make healthy food choices when dining out at a restaurant.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 15, '0', NULL, NULL);
