INSERT INTO `picturebooks` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(4, 'Floods', 'book_11339.pdf', 'thumb_339.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Do it with numbers, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Graeme Davis, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 155, 'Yes', '1000', 11339, 'Maths -Do it with numbers', 'Floods', NULL, 'What happens to the environment when a flood occurs? What are some of the causes of floods? What can people do about the problems caused because of  floods? How can you use your math skills to learn more about floods? Read this book to find the answers to these questions and learn more about floods.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 3, '0', NULL, NULL),
(5, 'Foals Grow up to Be Horses', 'book_4006.pdf', 'thumb_4006.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer:Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 4006, 'Habits and Essentials, Picture Books', 'Foals Grow up to Be Horses', NULL, 'Level 1 guided reader that introduces the concept of life cycles. Students will develop reading skills while learning how foals grow into horses.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(6, 'How Tall? How Wide?', 'book_409.pdf', 'thumb_409.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 409, 'Habits and Essentials, Picture Books', 'How Tall? How Wide?', NULL, 'Level 1 guided reader that introduces young students to the concepts of height and width while supporting the development of reading skills.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(7, 'It Is about Time!', 'book_410.pdf', 'thumb_410.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 410, 'Habits and Essentials', 'It Is about Time!', NULL, 'Level 1 guided reader that introduces young students to the concept of time while supporting the development of reading skills.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(8, 'Keep It Clean: Achoo!', 'book_411.pdf', 'thumb_411.jpeg', NULL, 'Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 411, 'Habits and Essentials, Picture Books', 'Keep It Clean: Achoo!', NULL, 'Level 1 guided reader that teaches students important lessons about germ control and staying healthy.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(9, 'Keep It Clean: Germ Free', 'book_412.pdf', 'thumb_412.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 412, 'Habits and Essentials, Picture Books', 'Keep It Clean: Germ Free', NULL, 'Level 1 guided reader that teaches students how to prevent the spread of germs by washing hands and the importance of cleanup.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(10, 'Keep It Clean: Get Well Soon', 'book_413.pdf', 'thumb_413.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author:Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 413, 'Habits and Essentials, Picture Books', 'Keep It Clean: Get Well Soon', NULL, 'Level 1 guided reader that teaches young readers about what happens when they get sick and what they can do to speed their recovery.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(11, 'Keep It Clean: Time to Wash Up', 'book_414.pdf', 'thumb_414.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author:Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 414, 'Habits and Essentials, Picture Books', 'Keep It Clean: Time to Wash Up', NULL, 'Level 1 guided reader that teaches students how to prevent the spread of germs by washing hands and the importance of cleanup.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(12, 'Kits Grow up to Be Rabbits', 'book_421.pdf', 'thumb_421.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author:  Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 421, 'Habits and Essentials, Picture Books', 'Kits Grow up to Be Rabbits', NULL, 'Level 1 guided reader that introduces the concept of life cycles. Students will develop reading skills while learning how kits grow into rabbits.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(15, 'Shapes Everywhere', 'book_424.pdf', 'thumb_424.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 424, 'Habits and Essentials, Picture Books', 'Shapes Everywhere', NULL, 'Level 1 guided reader that introduces young students to the concepts of shapes while supporting the development of reading skills.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(16, 'The World Around Us: Forests', 'book_425.pdf', 'thumb_425.jpg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 425, 'Science Explore', 'The World Around Us: Forests', NULL, 'Level 2 guided reader that teaches young readers about forests, how they grow and the ecosystems they support.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(17, 'The World Around Us Lakes', 'book_426.pdf', 'thumb_426.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 426, 'Habits and Essentials, Picture Books', 'The World Around Us Lakes', NULL, 'Level 2 guided reader that teaches the young reader important concepts about lakes, how they are formed, their importance in the ecosystems, and ways to keep them clean.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(19, 'The World Around Us Rivers', 'book_428.pdf', 'thumb_428.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 428, 'Habits and Essentials, Picture Books', 'The World Around Us: Rivers', NULL, 'Level 2 guided reader that teaches young readers concepts about rivers, how they are formed, their importance in the ecosystems, and ways to keep them clean.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(20, 'Tornadoes', 'book_11429.pdf', 'thumb_429.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 11429, 'Habits and Essentials, Picture Books', 'Tornadoes!', NULL, 'Level 2 guided reader that educates students on tornadoes, how they form, precaution, and safety.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(22, 'Wildfires', 'book_11999.pdf', 'thumb_999.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Do it with numbers, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Tamra B Orr, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 155, 'Yes', '1000', 11999, 'Maths -Do it with numbers, Early Concepts with Experiments', 'Wildfires', NULL, 'What happens to the environment when wildfires occur? What are some of the causes of wildfires? What can people do about the problems caused by wildfires? How can you use your math skills to learn more about wildfires? Read this book to find the answers to these questions and learn more about wildfires.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(25, 'Kittens Grow up to Be Cats', 'book_422.pdf', 'thumb_422.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 422, 'Habits and Essentials, Picture Books', 'Kittens Grow up to Be Cats', NULL, 'Level 1 guided reader that introduces the concept of life cycles. Students will develop reading skills while learning how kittens grow into adult cats.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(26, 'Puppies Grow up to Be Dogs', 'book_423.pdf', 'thumb_423.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 423, 'Habits and Essentials, Picture Books', 'Puppies Grow up to Be Dogs', NULL, 'Level 1 guided reader that introduces the concept of life cycles. Students will develop reading skills while learning how puppies grow into a full grown dogs.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(27, 'The World Around Us: Mountains', 'book_427.pdf', 'thumb_427.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 427, 'Habits and Essentials, Picture Books', 'The World Around Us: Mountains', NULL, 'Level 2 guided reader that teaches young readers concepts about mountains, how they are formed and the ecosystems they support.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(28, 'What Does It Weigh?', 'book_446.pdf', 'thumb_446.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Cecilia Minden, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 446, 'Maths -Do it with numbers, Habits and Essentials, Picture Books', 'What Does It Weigh?', NULL, 'Level 1 guided reader that introduces young students to the concept of weights while supporting the development of reading skills.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(29, 'Building a Volcano', 'book_405.pdf', 'thumb_405.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Brooke Rowe, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 135, 'Yes', '1000', 405, 'Early Concepts with Experiments', 'Building a Volcano', NULL, 'Each book in the My Science Fun series includes a simple experiment for the earliest readers. This book features step-by-step instructions on building a volcano while encouraging further exploration on the topic. Simple sentence structure and word usage help children develop word recognition and reading skills.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(30, 'Earthquakes!', 'book_404.pdf', 'thumb_404.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer:Science, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Lucia Raatma, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 404, 'Science Explorer, Habits and Essentials, Picture Books', 'Earthquakes!', NULL, 'Level 3 guided reader that teaches students about earthquakes, their causes and effects.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(31, 'Feelings: Sadness', 'book_406.pdf', 'thumb_406.jpg', NULL, 'Product details Age : 2 and up Series: Language Arts Explorer: Habits and Essentials No pf Pages: 24 pages Publisher: Aries Books International. (January 1, 2019) Author: Tamra B Orr Language: English Copyright: 2019 Graphics: Full Color Photographs', 135, 135, 'Yes', '1000', 406, 'Habits and Essentials', 'Feelings: Sadness', NULL, 'This Level 1 guided reader explores the feeling of sadness. Students will develop word recognition and reading skills while learning about their feelings.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(32, 'Inflating a Baloon', 'book_11407.pdf', 'thumb_407.jpg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Early Concepts with Experiments, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Brooke Rowe, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 135, 'Yes', '1000', 11407, 'Habits and Essentials, Early Concepts with Experiments', 'Inflating a Baloon', NULL, 'Each book in the My Science Fun series includes a simple experiment for the earliest readers. This book features step-by-step instructions on inflating a balloon while encouraging further exploration on the topic. Simple sentence structure and word usage help children develop word recognition and reading skills. Includes a glossary and index.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(33, 'Model T to Self-Driving Cars', 'book_11408.pdf', 'thumb_408.jpg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Jennifer Colby, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 135, 'Yes', '1000', 11408, 'Habits and Essentials, Picture Books', 'Model T to Self-Driving Cars', NULL, 'Technology is constantly progressing and changing. But have you ever stopped and wondered how it all started? In Model T to Self-Driving Cars, discover how the Model T evolved into the self-driving cars we have today. Engaging inquiry-based sidebars encourage young readers to think, create, guess, and ask questions about this technology. Book includes table of contents, glossary, index, author biographies, and sidebars.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL),
(34, 'Making Slime', 'book_4009.pdf', 'thumb_4009.jpeg', NULL, 'Product details, Age : 2 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Amy Quinn, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 135, 'Yes', '1000', 4009, 'Habits and Essentials', 'Making Slime', NULL, 'Making slime isn’t just fun. It’s also a great way to learn about chemistry! Through simple text written to foster creativity and problem solving, students will learn the art of innovation. Large, colorful images show students how to complete activities. Additional tools, including a glossary and an index, help students learn STEM concepts, new vocabulary, and locate information.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 3, '0', NULL, NULL);
INSERT INTO `planetsseries` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `isbn`, `categories`, `tags`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'Earth', 'book_71.pdf', 'thumb_71.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Planets & Earth’s Geography, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Charnan Simon, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 71, NULL, 'Planets & Earth\'s Geography, Picture Books, Early Concepts with Experiments', 'Earth', 'Learn where our home planet fits into the solar system, what it is made of, and why it is the only place we can live.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 4, '0', NULL, NULL),
(2, 'Jupiter', 'book_76.pdf', 'thumb_76.jpg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ariel kazunas, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 76, NULL, 'Planets & Earth\'s Geography, Picture Books', 'Jupiter', 'Learn all about Jupiter, our solar system’s largest planet, and its many moons.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 4, '0', NULL, NULL),
(4, 'Mercury', 'book_78.pdf', 'thumb_78.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ariel Kazunas, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 78, NULL, 'Planets & Earth\'s Geography, Picture Books', 'Mercury', 'Find out about the closest planet to the Sun and learn why its years are so short.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 4, '0', NULL, NULL),
(5, 'Neptune', 'book_79.pdf', 'thumb_79.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ariel Kazunas, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 79, NULL, 'Planets & Earth\'s Geography, Picture Book', 'Neptune', 'Travel to the far reaches of our solar system and learn about this distant, gaseous world.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 4, '0', NULL, NULL),
(6, 'Saturn', 'book_80.pdf', 'thumb_80.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ariel Kazunas, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 80, NULL, 'Planets & Earth\'s Geography, Picture Books', 'Saturn', 'Discover the beautiful ringed planet Saturn and its dozens of moons.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 4, '0', NULL, NULL),
(7, 'Uranus', 'book_81.pdf', 'thumb_81.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ariel Kazunas, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 81, NULL, 'Planets & Earth\'s Geography, Picture Books', 'Uranus', 'Learn all about the distant planet Uranus and its many moons and rings.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 4, '0', NULL, NULL),
(8, 'Venus', 'book_82.pdf', 'thumb_82.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Ariel Kazunas, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 82, NULL, 'Planets & Earth\'s Geography, Picture Books', 'Venu', 'Venus is the closest planet to Earth, and it is also very similar in size. Learn all about “Earth’s twin”.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 4, '0', NULL, NULL),
(9, 'Mars', 'book_77.pdf', 'thumb_77.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Charnan Simon, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 77, NULL, 'Planets & Earth\'s Geography, Picture Books', 'Mars', 'Discover what it’s like on the surface of the red planet and find out how space missions have helped scientists learn more about it.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 4, '0', NULL, NULL);
