INSERT INTO `powerup` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'Bio Fuels', 'book_92.pdf', 'thumb_92.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Frank Muschal, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 92, 'Science Explorer, Picture Books, Early Concepts with Experiments', 'Bio Fuels', NULL, 'We currently rely on nonrenewable sources, such as oil, for most of our fuel. Scientists are working on new fuels from crops and other materials to help ease future dependence on nonrenewable resources.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL),
(2, 'Coal', 'book_239.pdf', 'thumb_239.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Robert Green, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 239, 'Science Explorer', 'Coal', NULL, 'This title provides information on Coal as a source of energy. It highlights the positives and negatives of coal and discusses clean coal technology.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL),
(3, 'Electric Power Grid', 'book_101.pdf', 'thumb_101.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Patricia Hynes, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 101, 'Science Explorer, Picture Books', 'Electric Power Grid', NULL, 'Many little-know facts about electric power – and the grid that controls much of it – are explained in this fascinating book.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL),
(4, 'Energy From Hydrogen', 'book_103.pdf', 'thumb_103.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 103, 'Science Explorer, Picture Books', 'Energy From Hydrogen', NULL, 'The country’s “addiction” to oil is described and alternative energy potential from hydrogen is discussed.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL),
(5, 'From Waste to Energy', 'book_250.pdf', 'thumb_250.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Save the planet, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Robert, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 250, 'Save the Planet, Science Explorer', 'From Waste to Energy', NULL, 'This title provides information on one of most promising emerging sources of energy, waste. Provides a background on the opportunity and challenges associated with using waste to produce alternative energy.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL),
(6, 'Geothermal Energy', 'book_110.pdf', 'thumb_110.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Tamra B Orr, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 110, 'Science Explorer, Picture Books', 'Geothermal Energy', NULL, 'Long known as a potential power source, geothermal energy – heated water from within the Earth – is now being tapped. This book outlines those efforts and looks to the future.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL),
(7, 'Hydroelectric Energy', 'book_118.pdf', 'thumb_118.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Tamara B Orr, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 118, 'Science Explorer', 'Hydroelectric Energy', NULL, 'For years, people have used water power to provide electricity. This study recaps that history and describes exciting new techniques.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL),
(8, 'Nuclear Energy', 'book_127.pdf', 'thumb_127.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Kathleen Mannat, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 127, 'Science Explorer, Picture Books', 'Nuclear Energy', NULL, 'Nuclear energy, with the potential to provide vast amounts of power, is a controversial topic. The science, history, and the controversy are explained here.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL),
(9, 'Searching For Oil', 'book_141.pdf', 'thumb_141.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Kathleen Mannat, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 141, 'Science Explore', 'Searching For Oil', NULL, 'Oil is one of our most important natural resources. The searches for new sources – and options for alternative sources – are outlined here.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL),
(10, 'Energy from Wind Sun and Tides', 'book_014.pdf', 'thumb_014.jpeg', NULL, 'Age : 8 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Frank Muschal, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 145, 'Yes', '1000', 14, 'Science Explorer', 'Energy from Wind Sun and Tides', NULL, 'Recent advances in harnessing energy from the wind, sun, and tides are explored. People are encouraged to seek resources beyond fossil fuels.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 26, '0', NULL, NULL);
INSERT INTO `realworldscience` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'A Changing Earth', 'book_156.pdf', 'thumb_156.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Planets & Earth’s Geography, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Heather, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 156, 'Planets & Earth\'s Geography, Picture Books', 'A Changing Earth', NULL, 'The Hands on Science series provides students with background on key concepts in Science. Each title includes engaging hands on exercises that bring the concepts to life for kids. Real World Science: A Changing Earth, provide information on how landforms change, how mountains form, what causes volcanoes and earthquakes, and the movement of continents.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL),
(2, 'Animals', 'book_159.pdf', 'thumb_159.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Its cool to learn about countries, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Stuart Levine, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 159, 'Learning About Animals, Picture Book', 'Animals', NULL, 'The Hands on Science series provide students with background on key concepts in Science. Each title includes engaging hands on exercises that help bring the concepts to life for kids. Real World Science: Animals, provide information on the basic needs of animals, and the body parts and behaviors that help animals meet their needs.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL),
(3, 'Ecosystems', 'book_176.pdf', 'thumb_176.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Matt Mulins, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 176, 'Science Explorer, Planets & Earth\'s Geography', 'Ecosystems', NULL, 'The Hands on Science series provides students with background on key concepts in Science. Each title includes engaging hands on exercises that bring the concepts to life for kids. Real World Science: Ecosystems, examine and define what are ecosystems, how living things get energy in an ecosystem, competing and surviving in an ecosystem, and extinction and its causes', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL),
(4, 'Matter', 'book_11189.pdf', 'thumb_189.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Heather Miller, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 11189, 'Science Explorer, Picture Books', 'Matter', NULL, 'The Hands on Science series provides students with background on key concepts in Science. Each title includes engaging hands on exercises that bring the concepts to life for kids. Real World Science: Matter, covers the topics of what is a solid, liquid, and gas, how to measure and compare matter, and the useful properties of matter.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL),
(5, 'Plants', 'book_198.pdf', 'thumb_198.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Elizabeth Silverthorne, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 198, 'Save the Planet, Science Explorer', 'Plants', NULL, 'The Hands on Science series provides students with background on key concepts in Science. Each title includes engaging hands on exercises that bring the concepts to life for kids. Real World Science: Plants, provide information on the basic needs of plants, parts of plants that help them grow and thrive, and how plants reproduce.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL),
(6, 'Soil', 'book_208.pdf', 'thumb_208.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Sharpe, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 208, 'Science Explorer, Habits and Essentials', 'Soil', NULL, 'The Hands on Science series provides students with background on key concepts in Science. Each title includes engaging hands on exercises that bring the concepts to life for kids. Real World Science: Soil, provides students with information on the importance of soil, how soil forms, properties of soil, soil loss, and conserving soil.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL),
(7, 'Earth’s Biomes', 'book_175.pdf', 'thumb_175.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katy S, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 175, 'Science Explorer, Picture Books', 'Earth’s Biomes', NULL, 'The Hands on Science series provides students with background on key concepts in Science. Each title includes engaging hands on exercises that bring the concepts to life for kids. Real World Science: Earth’s Biomes, include information on tropic rain forests, deciduous forests, grasslands, deserts, taiga, and tundra.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL),
(8, 'Electricity and Magnetism', 'book_177.pdf', 'thumb_177.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Dana, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', 'Electricity and Magnetism', 177, 'Science Explorer', 'Electricity and Magnetism', NULL, 'The Hands on Science series provides students with background on key concepts in Science. Each title includes engaging hands on exercises that bring the concepts to life for kids. Real World Science: Electricity and Magnetism, provides information on static electricity, electric current, magnets, and electromagnets', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL),
(9, 'Protecting Ecosystems', 'book_199.pdf', 'thumb_199.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019) Author: Leanne Currie, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'No', '1000', 199, 'Save the Planet, Science Explorer', 'Protecting Ecosystems', NULL, 'The Hands on Science series provides students with background on key concepts in Science. Each title includes engaging hands on exercises that bring the concepts to life for kids. Real World Science: Protecting Ecosystems, provide information on natural changes vs. changes brought about by people, wise use of ecosystems, and restoring damaged ecosystems.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL),
(10, 'Rocks and Minerals', 'book_201.pdf', 'thumb_201.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Dana, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 201, 'Science Explorer', 'Rocks and Minerals', NULL, 'The Hands on Science series provides students with background on key concepts in Science. Each title includes engaging hands on exercises that bring the concepts to life for kids. Real World Science: Rocks and Minerals, provide background on rocks and minerals, what they are and how they form, how rocks change, and the uses of rocks and minerals.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 24, '0', NULL, NULL);
