(21, 'States of Matter', 'book_285.pdf', 'thumb_285.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Matt Mullin, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 285, 'Early Concepts with Experiments', 'States of Matter', NULL, 'Following the scientific process, this title provides instructions on how to conduct experiments that help students gain a better understanding of the states of matter.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(22, 'Water', 'book_289.pdf', 'thumb_289.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Concept with Experiments, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Charman Simon, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 289, 'Early Concepts with Experiments', 'Water', NULL, 'Following the scientific process, this title provides instructions on how to conduct experiments that help students gain a better understanding of the property of water.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(23, 'Weather', 'book_290.pdf', 'thumb_290.png', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 290, 'Habits and Essentials, Planets & Earth\'s Geography, Early Concepts with Experiments', 'Weather', NULL, 'Following the scientific process, this title provides instructions on how to conduct experiments that help students gain a better understanding of the earth’s weather.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(24, 'Compounds and Mixtures', 'book_240.pdf', 'thumb_240.jpg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 240, 'Science Explorer, Early Concepts with Experiments', 'Compounds and Mixtures', NULL, 'Following the scientific process, this title provides instructions on how to conduct experiments that help students gain a better understanding of compounds and mixtures.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(25, 'Digestion', 'book_242.pdf', 'thumb_242.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer:Science, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Tamra B Orr, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 242, 'Science Explorer, Habits and Essentials', 'Digestion', NULL, 'Following the scientific process, this title provides instructions on how to conduct experiments that help students gain a better understanding of the body and digestion.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(26, 'Science Lab: Gases', 'book_911.pdf', 'thumb_911.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Shirley Smith Duke, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 911, 'Science Explorer', 'Science Lab: Gases', NULL, 'The focus of the book is on gases. The reader is encouraged to make predictions, perform purpose-driven research, and creatively solve problems presented about gases.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(27, 'Science Lab: Motion and Forces', 'book_9.pdf', 'thumb_9.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Barker, David M, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 9, 'Science Explorer', 'Science Lab: Motion and Forces', NULL, 'The focus of the book is on motion and forces. The reader is encouraged to make predictions, perform purpose-driven research, and creatively solve problems presented about motion and forces.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(28, 'Science Lab: Properties of Matter', 'book_11.pdf', 'thumb_11.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Rebecca Hirsch, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 11, 'Science Explorer', 'Science Lab: Properties of Matter', NULL, 'Using the narrative voice of a student attending a science camp, this book delves into the properties of matter while engaging the readers in the process of scientific inquiry.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(29, 'Science Lab: Technological Design', 'book_13.pdf', 'thumb_13.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Lynn.A Sirota, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 13, 'Science Explorer', 'Science Lab: Technological Design', NULL, 'This book explains the concept of technological design. The reader is encouraged to make predictions, perform purpose-driven research, and creatively solve problems presented about technological design.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(30, 'Science Lab: The Life Cycles of Plants', 'book_14.pdf', 'thumb_14.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author:Rebecca Hirsch, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 14, 'Science Explorer', 'Science Lab: The Life Cycles of Plants', NULL, 'Written in the narrative voice of an inquisitive student, this book explains the life cycles of plants. Readers begin to understand how the process of forming and answering questions is a key to investigation and scientific communication.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(31, 'Science Lab: The Transfer of Energy', 'book_15.pdf', 'thumb_15.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Christine, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 15, 'Science Explorer', 'Science Lab: The Transfer of Energy', NULL, 'The focus of this book is on the transfer of energy. The reader is encouraged to make predictions, perform purpose-driven research, and creatively solve problems presented about the transfer of energy.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL),
(32, 'Science Lab: Weather Patterns', 'book_16.pdf', 'thumb_16.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Science Lab, No pf Pages: 32 pages, Publisher: Aries Books International. (January 1, 2019), Author: Carol Hand, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 145, 165, 'Yes', '1000', 16, 'Science Explorer', 'Science Lab: Weather Patterns', NULL, 'Written in the narrative voice of a budding meteorologist, this book explains weather patterns. Readers begin to understand how the process of forming and answering questions is a key to investigation and scientific communication.', 'Weight : 9.6 g, Dimensions : 7.5 × 9.5 × 4 cm', 20, '0', NULL, NULL);
