INSERT INTO `whatshoudido` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `isbn`, `categories`, `tags`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(1, 'What Should I Do At The Pool', 'book_460.pdf', 'thumb_460.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 460, NULL, 'Habits and Essentials, Picture Books', 'What Should I Do At The Pool', 'Readers learn the potential dangers of swimming and learn how to avoid injury.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 12, '0', NULL, NULL),
(2, 'What Should I Do? If a Stranger Comes Near', 'book_461.pdf', 'thumb_461.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 461, NULL, 'Habits and Essentials, Picture Books', 'What Should I Do? If a Stranger Comes Near', 'Readers will learn how to stay safe by avoiding strangers as well as what they can do if strangers approach them.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 12, '0', NULL, NULL),
(3, 'What Should I Do If There Is A Fire', 'book_463.pdf', 'thumb_463.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 463, NULL, 'Habits and Essentials, Picture Books', 'What Should I Do? If There Is a Fire', 'Readers learn what to do if they are caught in a burning building, how to prepare for such events ahead of time, and how to react to firefighters.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 12, '0', NULL, NULL),
(4, 'What Should I Do In The Car', 'book_464.pdf', 'thumb_464.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs,', 135, 145, 'Yes', '1000', 464, NULL, 'Habits and Essentials, Picture Books', 'What Should I Do? In the Car', 'The potential dangers of riding in automobiles are presented, and readers are taught about seatbelt safety and how to avoid distracting a driver.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 12, '0', NULL, NULL),
(5, 'What Should I Do? On My Bike', 'book_466.pdf', 'thumb_466.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 466, NULL, 'Habits and Essentials, Picture Books', 'What Should I Do? On My Bike', 'Readers are taught how to care for their bicycles and avoid situations that could result in injury.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 12, '0', NULL, NULL),
(6, 'What Should I Do? Near a Busy Street', 'book_465.pdf', 'thumb_465.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 465, NULL, 'Habits and Essentials, Picture Books', 'What Should I Do? Near a Busy Street', 'Safety rules are presented for playing or traveling near busy streets, and readers are taught how to alert adults in case of an emergency.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 12, '0', NULL, NULL),
(7, 'What Should I Do? On the Playground', 'book_467.pdf', 'thumb_467.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 467, NULL, 'Habits and Essentials, Picture Books', 'What Should I Do? On the Playground', 'Playground safety rules are explained clearly, and readers are taught how to avoid dangerous equipment and irresponsible children as they play.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 12, '0', NULL, NULL),
(8, 'What Should I Do If Stray Animal Comes-Near', 'book_1467.pdf', 'thumb_1467.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Nancy Robinson, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 1467, NULL, NULL, NULL, 'Readers will learn how to stay safe by avoiding strangers as well as what they can do if strangers approach them.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 12, '0', NULL, NULL);
INSERT INTO `whatsyourhealthyplate` (`id`, `book_title`, `book_path`, `thumb_img`, `product_img`, `product_details`, `actual_price`, `offer_price`, `sale`, `in_stock`, `sku`, `categories`, `tags`, `isbn`, `description`, `additional_info`, `categories_id`, `review`, `created_at`, `updated_at`) VALUES
(2, 'Your Healthy Plate: Grains', 'book_470.pdf', 'thumb_470.jpeg', NULL, 'Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 470, 'Habits and Essentials, Picture Books', 'Your Healthy Plate: Grains', NULL, 'This new book from Aries Books International, highlights grains, one of the food groups contained in the new dietary guidelines for Americans launched in January 2011 by the FDA. This leveled reader helps the young child understand the importance of grains as a part of a balanced diet.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 2, '0', NULL, NULL),
(3, 'Your Healthy Plate: Oils and Fats', 'book_471.pdf', 'thumb_471.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 471, 'Habits and Essentials, Picture Books', 'Your Healthy Plate: Oils and Fats', NULL, 'This new book from Aries Books International, highlights oils one of the key components contained in the new dietary guidelines for Americans launched in January 2011 by the FDA. This leveled reader helps the young child understand the importance of oils as a part of a balanced diet.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 2, '0', NULL, NULL),
(4, 'Your Healthy Plate: Vegetables', 'book_473.pdf', 'thumb_473.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'Yes', '1000', 473, 'Habits and Essentials, Picture Books', 'Your Healthy Plate: Vegetables', NULL, 'This new book from Aries Books International highlights vegetables, one of the food groups contained in the new dietary guidelines for Americans launched in January 2011 by the FDA. This leveled reader helps the young child understand the importance of vegetables as a part of a balanced diet.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 2, '0', NULL, NULL),
