(6, 'Your Healthy Plate: Protein', 'book_472.pdf', 'thumb_472.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 472, 'Habits and Essentials, Picture Books', 'Your Healthy Plate: Protein', NULL, 'This new book from Aries Books International, highlights protein, one of the food groups contained in the new dietary guidelines for Americans launched in January 2011 by the FDA. This leveled reader helps the young child understand the importance of protein as a part of a balanced diet.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 2, '0', NULL, NULL),
(7, 'Your Healthy Plate: Fruits', 'book_469.pdf', 'thumb_469.jpeg', NULL, 'Product details, Age : 3 and up, Series: Language Arts Explorer: Habits and Essentials, No pf Pages: 24 pages, Publisher: Aries Books International. (January 1, 2019), Author: Katie Marsico, Language: English, Copyright: 2019, Graphics: Full Color Photographs', 135, 145, 'No', '1000', 469, 'Habits and Essentials, Picture Books', 'Your Healthy Plate: Fruits', NULL, 'This new book from Aries Books International highlights Fruit, one of the food groups contained in the new dietary guidelines for Americans launched in January 2011 by the FDA. This leveled reader helps the young child understand the importance of fruit as a part of a balanced diet.', 'Weight : 9.6 g, Dimensions : 8.25 × 8.25 × 4 cm', 2, '0', NULL, NULL);
